-- 刷新 红三栏 文本信息
-- 同时将 "0/3" 总完成个数立刻写到 redThreeTxtNumber 上
function MazeMainUI:RefreshRedThreeTextDatas( isNeedNewServerData_ )

    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---@type MapDecryptionComponent
        local component = MapDecryptionMgr:GetComponent()

        -- 每次战斗和领取宝箱后, 都要刷新数据
        if isNeedNewServerData_ == true then
            local isFinish = false
            GameUtils.Request(Interfaces.ActivityMapDecryptionHome, {activityUuid = component:GetActivityData().id}, function(request, response)
                if checkNumber(response.errCode) ~= 0 then return end
                MapDecryptionMgr:GetComponent():Initial(response.data)
                isFinish = true
            end)

            while not isFinish do
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
        end

        ---@type MapDecryptionDojo
        local mapDecryptionHomeDatas = component:GetMapDecryptionDojo()

        if
            isNotNull(mapDecryptionHomeDatas) and 
            isNotNull(Maze2DStates.mapId) and 
            isNotNull(mapDecryptionHomeDatas.maps) and 
            isNotNull(mapDecryptionHomeDatas.maps[ checkInt(Maze2DStates.mapId) ])
        then

                -- 测试:
                -- assert( not isNull(mapDecryptionHomeDatas) )
                -- assert( not isNull(Maze2DStates.mapId) )
                -- assert( not isNull(mapDecryptionHomeDatas.maps) )
                -- assert( not isNull(mapDecryptionHomeDatas.maps[ checkInt(Maze2DStates.mapId) ]) )

            local tasks = mapDecryptionHomeDatas.maps[ checkInt(Maze2DStates.mapId) ].tasks
            --assert( not isNull(tasks) )

            if isNotNull(tasks) then

                self.redThreeTextDatas = {}
                local finishedNum = 0        
                for i=1,3 do 
                    table.insert( self.redThreeTextDatas,{
                        baseText = tasks[i].desc,
                        progress = tasks[i].progress,
                        targetNum = tasks[i].targetNum,
                    })
                    if tonumber(tasks[i].progress) == tonumber(tasks[i].targetNum) then 
                        finishedNum = finishedNum + 1
                    end 
                end
                --  
                self.redThreeTxtNumber.text = tostring(finishedNum) .. "/3"

                -- debug: 
                for k,v in pairs(self.redThreeTextDatas) do 
                    print( "baseText: " .. v.baseText .. ", progress: " .. v.progress .. ", targetNum: " .. v.targetNum )
                end 

            end

        end

    end))
    return coWait
end




---@param btn UnityEngine.UI.Button
---@return void
function MazeMainUI:PlayBtnPushAnimation( btn )
    assert( not isNull(btn) )
    assert( not isNull(self.btnAnimations[btn]) )
    assert( not isNull(self.btnPressedAnimationNames[btn] ) )
    self.btnAnimations[btn]:Play( self.btnPressedAnimationNames[btn] )
end


---@param btn     UnityEngine.UI.Button
---@param isShow  boolean -- show or hide
---@return void
function MazeMainUI:PlayBtnHideOrShowAnimation( btn, isShow )
    assert( not isNull(btn) )
    assert( not isNull(self.btnAnimations[btn]), "btn name = " .. btn.gameObject.name )
    assert( not isNull(self.btnShowAnimationNames[btn] ) )
    assert( not isNull(self.btnHideAnimationNames[btn] ) )
    if isShow then
        self.btnAnimations[btn]:Play( self.btnShowAnimationNames[btn] )
    else 
        self.btnAnimations[btn]:Play( self.btnHideAnimationNames[btn] )
    end
end




