-- 开启 红三条
---@return System.Collections.IEnumerator
function MazeMainUI:OpenTaskNode()

    print("开启 taskNode");
    local tileWaitTime = 0.2 -- float
    local tileWaitTime2 = 0.07 -- float

    -- --- 隐藏 redThreeBtnTarget: (动画渐隐)
    self.BtnTargetAnimation:Play("SpringFestivalMazeMainDialog_BtnTarget_Pressed")
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime))
    MazeMainUI.SetBtnActive( self.redThreeBtnTarget, false )

    -- --- 显示 redThreeBtnPutAway: (直接显示不播动画)
    self.BtnPutAwayAnimation:Play("SpringFestivalMazeMainDialog_BtnPutAway_Return")
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime))
    MazeMainUI.SetBtnActive( self.redThreeBtnPutAway, true )
    MazeMainUI.SetBtnActive( self.fullAreaBtn, true )

    self.targetInfoOrNodeAnimations = {} -- clear
   
    -- --- 依次展开 1~3 段条目 -- todo: 这个应该 根据需求来定 
    for i=1, 3 do
        local newgo = Object.Instantiate( self.redThreeTargetInfoOrNode.gameObject, self.InfoList.transform ) -- GameObject
        local newBH  = KTool.GetComponent(newgo, typeof(LuaBehaviour)).Env  -- LuaBehaviour
        assert( newBH )

        local redThreeTextData = self.redThreeTextDatas[i]

        newBH.textComp.text = redThreeTextData.baseText -- 写入文本

        if redThreeTextData.progress == redThreeTextData.targetNum then 
            -- 已经完成, 显示 "打勾"
            KTool.SetActive( newBH.finishAnimNode.gameObject, true )
            KTool.SetActive( newBH.progressTextComp.gameObject, false )
        else 
            -- 尚未完成, 显示 分子分母
            KTool.SetActive( newBH.finishAnimNode.gameObject, false )
            KTool.SetActive( newBH.progressTextComp.gameObject, true )
            newBH.progressTextComp.text = "(" .. redThreeTextData.progress .. "/" .. redThreeTextData.targetNum .. ")"
        end

        local animation = newBH.animation
        animation:Play("SpringFestivalMazeMainDialog_TrainingTarget_Cell_Open")
        table.insert( self.targetInfoOrNodeAnimations, animation )
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime2))
    end
    ---
    self.redThreePanelState = PanelState.Opened
end

    
-- 关闭 红三条
---@return System.Collections.IEnumerator
function MazeMainUI:CloseTaskNode()

    print("关闭 taskNode");
    local tileWaitTime = 0.2 -- float
    local tileWaitTime2 = 0.1 -- float

    -- --- 逐个释放 数个条目
    for i=#self.targetInfoOrNodeAnimations, 1, -1 do 
        
        local anim = self.targetInfoOrNodeAnimations[i] -- Animation
        table.remove( self.targetInfoOrNodeAnimations ) -- 默认删除尾元素
        anim:Play( "SpringFestivalMazeMainDialog_TrainingTarget_Cell_Closed" )
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime2))
        Object.Destroy( anim.gameObject )
    end

    -- --- 隐藏 redThreeBtnPutAway: 
    self.BtnPutAwayAnimation:Play("SpringFestivalMazeMainDialog_BtnPutAway_Pressed")
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime))
    MazeMainUI.SetBtnActive( self.redThreeBtnPutAway, false )
    MazeMainUI.SetBtnActive( self.fullAreaBtn, false )
    
    -- --- 显示 redThreeBtnTarget: 
    self.BtnTargetAnimation:Play("SpringFestivalMazeMainDialog_BtnTarget_Return")
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime))
    MazeMainUI.SetBtnActive( self.redThreeBtnTarget, true )
    ---
    self.redThreePanelState = PanelState.Closed
    --Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl - 1 -- !!! Must
    Maze2DStates.MinusIsInAutoControl() -- !!! Must 
end


-- 开启 提示窗口 - 按钮触发
---@return void
function MazeMainUI:WhenOpenTipsPopup()

    --if Maze2DStates.isInAutoControl <= 0  then
    if Maze2DStates.IsInAutoControlLegal() == true  then

        -- 红三条 不关闭时, 本按钮无效
        if self.redThreePanelState == PanelState.Closed then
            self:Open_TipsPopup()
        end
    end 
end



function MazeMainUI:Open_TipsPopup()
    --Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl + 1 -- !!! Must
    Maze2DStates.AddIsInAutoControl() -- !!! Must 
    local co_3 = cs_coroutine.start(function()

        self.TipsPopup.gameObject:SetActive(true)
        self.TipsPopup_RootAnimation:Play("SpringFestivalMazeTipsPopup_Root")
        self.TipsPopupState = PanelState.Opened

    end)
    table.insert( self.coroutineRets, co_3 )
end



function MazeMainUI:Open_TipsPopup_AndWait()
    self:Open_TipsPopup()
    while self.TipsPopupState == PanelState.Opened do 
        coroutine.yield(Yielders.EndOfFrame)
    end
end


-- 关闭提示窗口
---@return void
function MazeMainUI:WhenCloseTipsPopup()
    
    self.TipsPopup_BtnCloseAnimation:Play("UI_Common_ButtonPressed")
    self.TipsPopup.gameObject:SetActive(false)

    self.TipsPopupState = PanelState.Closed
    --Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl - 1 -- !!! Must
    Maze2DStates.MinusIsInAutoControl() -- !!! Must 
    
end




function MazeMainUI.SetBtnActive( btn_, isActive )
    assert( btn_ )
    btn_.gameObject:SetActive( isActive )
end



return MazeMainUI